import fs from 'node:fs/promises';
import http from 'node:http';

// ❌ OLD: Node reads bytes from disk into a libuv worker thread,
// copies bytes into a V8 Buffer on the main thread, and writes to socket.
http.createServer(async (req, res) => {
  const data = await fs.readFile('./large-video.mp4');
  res.setHeader('Content-Type', 'video/mp4');
  res.end(data);
}).listen(3000);

// ✅ NEW: Bun passes the file descriptor directly to the HTTP server.
// Bytes are piped directly in the OS kernel via sendfile(2) with 0 JS memory overhead!
Bun.serve({
  port: 3000,
  fetch(req) {
    return new Response(Bun.file('./large-video.mp4'));
  }
});
